 if(form.id==='editHistoryForm'){const p=getProduct(form.dataset.id);if(!p)return true;const title=String(fd.get('title')||'').trim(),date=calendarDate(fd.get('date')),cost=fd.get('cost');if(!title||!date||cost!==''&&(!Number.isFinite(Number(cost))||Number(cost)<0)){toast('Titel, gültiges Datum und nicht-negative Kosten prüfen.');return true;}const h=p.history.find(h=>h.id===form.dataset.historyId),next={id:h?.id||uid('hist'),type:fd.get('type'),title,date,details:String(fd.get('details')||'').trim(),cost,currency:fd.get('currency')==='USD'?'USD':'EUR',...Object.fromEntries(['problem','cause','repair','part','workshop','outcome','documentId'].map(k=>[k,String(fd.get(k)||'').slice(0,500)])),public:fd.has('public')};if(next.type==='purchase'&&(fd.has('updatePurchaseDate')||fd.has('updatePurchasePrice')))next.purchaseLinked=true;if(h)Object.assign(h,next);else p.history.push(next);p.qrCreatedAt=new Date().toISOString();if(next.type==='purchase'){if(fd.has('updatePurchaseDate'))p.purchaseDate=date;if(fd.has('updatePurchasePrice')){p.price=cost;p.currency=next.currency;}if(h&&PassPilotLifecycle.linked(h)&&((!fd.has('updatePurchaseDate')&&p.purchaseDate&&date!==p.purchaseDate)||(!fd.has('updatePurchasePrice')&&(String(cost)!==String(p.price)||next.currency!==p.currency))))h.purchaseDetached=true;}saveState();PassPilotLifecycle.finish(p,form);return true;}
 if(form.id==='safeTransferForm'){const options={};for(const key of ['location','serial','name','photo','partNumber'])options[key]=fd.has(key);options.recipient=fd.get('recipient');await exportTransfer(form.dataset.id,options);closeModal();openProduct(form.dataset.id);return true;}
 if(form.id==='importChoices'){const current=pendingImport;if(!current)return true;const result={};for(const row of current.rows)result[row.index]=fd.get('choice-'+row.index)||'skip';pendingImport=null;current.resolve(result);closeModal();return true;}
