function reminderModal(id){const p=getProduct(id);modal(`<div class="modal-head"><h2>Erinnerungsfristen</h2><button class="icon-btn" data-action="close-modal">✕</button></div><form id="reminderForm" data-id="${esc(id)}"><p>Gilt für Rückgabe, Garantie und Wartungsdatum. Lokale System-Erinnerungen zuerst unter Einstellungen erlauben.</p>${[30,14,7,3,1,0].map(n=>`<label class="checkbox-row"><input type="checkbox" name="offset" value="${n}" ${(p.reminders||[]).includes(n)?'checked':''}> ${n?n+' Tage vorher':'Am Fälligkeitstag'}</label>`).join('')}<button class="primary-btn">Speichern</button></form>`);}
