function serviceModal(id){const p=getProduct(id);const examples=p.category==='ebike'?'Kette, Bremsen, Reifen, Inspektion, Akku':p.category==='camera'?'Sensorreinigung, Objektivprüfung':'Filter, Reinigung, Verschleißteile';modal(`<div class="modal-head"><h2>Wartungsplan anlegen</h2><button class="icon-btn" data-action="close-modal">✕</button></div><form id="servicePlanForm" data-id="${esc(id)}"><p>Beispiele: ${examples}. Das passende Intervall selbst anhand der Herstellerangaben wählen.</p><div class="form-grid">${input('title','Wartung')}${input('interval','Intervall',12,'number')}<div class="field"><label>Einheit</label><select name="unit"><option value="months">Monate</option><option value="km">Kilometer</option><option value="hours">Betriebsstunden</option></select></div>${input('current','Aktueller Zählerstand (km / Stunden)',0,'number')}${input('date','Letzte Wartung / Startdatum',localDate(),'date')}</div><button class="primary-btn">Plan speichern</button></form>`);}
function completeService(id,planId){const p=getProduct(id),plan=p?.maintenancePlans.find(t=>t.id===planId);if(!plan)return;if(plan.unit==='months'){if(!confirm('Wartung heute als erledigt speichern?'))return;plan.date=localDate();plan.due=addMonths(plan.date,plan.interval);p.nextMaintenance=plan.due;}else{const value=prompt('Aktueller Zählerstand in '+(plan.unit==='km'?'km':'Stunden')+':',String(plan.current));if(value===null)return;const n=Number(value);if(!Number.isFinite(n)||n<plan.last)return toast('Gültigen, nicht sinkenden Zählerstand eingeben.');plan.current=n;if(n-plan.last<plan.interval){saveState();openProduct(id);return toast('Zählerstand gespeichert. Wartungsintervall noch nicht erreicht.');}if(!confirm('Wartung als erledigt speichern und Intervall neu starten?')){saveState();openProduct(id);return;}plan.last=n;}p.history.push({id:uid('hist'),type:'maintenance',date:localDate(),title:plan.title,details:'Wartungsplan erledigt',public:false});saveState();openProduct(id);}
function productInfoModal(id){const p=getProduct(id);modal(`<div class="modal-head"><h2>Produktinformationen</h2><button class="icon-btn" data-action="close-modal">✕</button></div><form id="productInfoForm" data-id="${esc(id)}"><p>Freiwillige Angaben aus Herstellerunterlagen. Keine Verifizierung oder offizieller EU-Produktpass. Besitzerinformationen sind getrennt und werden nicht veröffentlicht.</p>${['materials','origin','repairability','spares','recycling'].map((k,i)=>`<div class="field"><label>${['Materialien','Herkunft','Reparierbarkeit / Reparaturinformationen','Ersatzteile','Recycling'][i]}</label><textarea name="${k}">${esc(p.productInfo[k]||'')}</textarea></div>`).join('')}<button class="primary-btn">Speichern</button></form>`);}
function passwordPrompt(title){return new Promise(resolve=>{pendingPassword=resolve;modal(`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal">✕</button></div><form id="passwordForm"><p>Passwort gut aufbewahren. Ohne Passwort ist keine Wiederherstellung möglich.</p><div class="field"><label>Passwort (mindestens 10 Zeichen)</label><input type="password" name="password" required minlength="10" autocomplete="off"></div><button class="primary-btn">Weiter</button></form>`);});}
const bytesTo64=bytes=>{let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s);};
const from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function keyFor(password,salt){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
function validateBackup(payload){if(payload.format!=='passpilot-backup'||!Array.isArray(payload.state?.products)||!Array.isArray(payload.files))throw Error('Backup-Struktur ungültig.');for(const p of payload.state.products)for(const doc of p.documents||[])if(doc.kind!=='link'&&!payload.files.some(f=>f.productId===p.id&&f.doc?.id===doc.id&&f.data))throw Error('Backup unvollständig: Datei '+doc.name+' fehlt.');return true;}
async function encryptedBackup(){const password=await passwordPrompt('Backup verschlüsseln');if(!password)return;const payload=await backupPayload();validateBackup(payload);const plain=new TextEncoder().encode(JSON.stringify(payload)),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await keyFor(password,salt),encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);const envelope={format:'passpilot-encrypted',version:1,algorithm:'AES-256-GCM',kdf:'PBKDF2-SHA256',iterations:250000,salt:bytesTo64(salt),iv:bytesTo64(iv),data:bytesTo64(new Uint8Array(encrypted))};const verified=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,encrypted);validateBackup(JSON.parse(new TextDecoder().decode(verified)));await downloadJson(envelope,'PassPilot-Backup-verschluesselt.json');state.settings.lastBackupAt=new Date().toISOString();saveState();toast('Verschlüsseltes Backup gespeichert und intern geprüft.');}
async function decryptBackup(envelope){if(envelope.version!==1||envelope.iterations!==250000||envelope.algorithm!=='AES-256-GCM'||envelope.kdf!=='PBKDF2-SHA256')throw Error('Unbekannte Backup-Verschlüsselung.');const salt=from64(envelope.salt),iv=from64(envelope.iv);if(salt.length!==16||iv.length!==12)throw Error('Backup beschädigt.');const password=await passwordPrompt('Backup entsperren');if(!password)return null;try{const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},await keyFor(password,salt),from64(envelope.data));const payload=JSON.parse(new TextDecoder().decode(plain));validateBackup(payload);return payload;}catch(e){throw Error('Falsches Passwort oder beschädigtes Backup.');}}
